export type SiteContent={heroHeading:string;heroBody:string;announcement:string;promoHeading:string;promoBody:string;footerDescription:string;supportEmail:string};
export type CommerceSettings={guestPricing:'hidden'|'visible';defaultTier:string;minimumOrder:number;lowStockThreshold:number;applicationApproval:'manual'|'automatic';verifiedReviews:boolean;market:string;currency:string;language:string};
export const defaultSiteContent:SiteContent={heroHeading:'Better sourcing starts with a partner built to deliver.',heroBody:'Fragrance, beauty, toys, collectibles, drinkware and everyday merchandise—organized for qualified wholesale buyers and backed by decades of distribution experience.',announcement:'Serving qualified businesses with professional wholesale distribution.',promoHeading:'Fresh inventory for the next retail moment.',promoBody:'Explore new fragrance, beauty, toys, collectibles, drinkware and everyday merchandise selected for modern retail assortments.',footerDescription:'A modern wholesale partner built on decades of distribution experience. Serving qualified retailers across fragrance, beauty, toys, collectibles, drinkware and general merchandise.',supportEmail:'support@example.com'};
export const defaultCommerceSettings:CommerceSettings={guestPricing:'hidden',defaultTier:'Standard Wholesale',minimumOrder:500,lowStockThreshold:30,applicationApproval:'manual',verifiedReviews:true,market:'United States',currency:'USD',language:'English'};
const read=<T,>(key:string,fallback:T):T=>{if(typeof window==='undefined')return fallback;try{return{...fallback,...JSON.parse(localStorage.getItem(key)||'{}')}}catch{return fallback}};
export const getSiteContent=()=>read('ms-admin-site-content',defaultSiteContent);
export const saveSiteContent=(value:SiteContent)=>{if(typeof window!=='undefined'){localStorage.setItem('ms-admin-site-content',JSON.stringify(value));window.dispatchEvent(new Event('meridian-content-updated'))}};
export const getCommerceSettings=()=>read('ms-admin-commerce-settings',defaultCommerceSettings);
export const saveCommerceSettings=(value:CommerceSettings)=>{if(typeof window!=='undefined')localStorage.setItem('ms-admin-commerce-settings',JSON.stringify(value))};
export const loadAdminRows=(key:string,fallback:string[][]):string[][]=>{if(typeof window==='undefined')return fallback;try{const v=JSON.parse(localStorage.getItem('ms-admin-'+key)||'null');return Array.isArray(v)?v:fallback}catch{return fallback}};
export const saveAdminRows=(key:string,rows:string[][])=>{if(typeof window!=='undefined')localStorage.setItem('ms-admin-'+key,JSON.stringify(rows))};
export const appendAdminRow=(key:string,row:string[])=>{if(typeof window==='undefined')return;const current=loadAdminRows(key,[]);saveAdminRows(key,[row,...current])};
