import{useMemo,useState}from'react';import{Check,ThumbsUp,ThumbsDown,Image as ImageIcon,PenLine,ShieldCheck}from'lucide-react';import{Product}from'../data/products';import{getMockReviews,ratingBreakdown,Review}from'../data/reviews';import{appendAdminRow}from'../data/siteConfig';
export default function ReviewSystem({product}:{product:Product}){const[filter,setFilter]=useState<'all'|'verified'|'photos'>('all');const[sort,setSort]=useState('relevant');const[form,setForm]=useState(false);const[submissions,setSubmissions]=useState<Review[]>([]);const[votes,setVotes]=useState<Record<string,'up'|'down'>>({});const[reported,setReported]=useState<string[]>([]);const reviews=useMemo(()=>{let a=[...submissions,...getMockReviews(product.id)].filter(r=>filter==='verified'?r.verified:filter==='photos'?r.hasPhotos:true);if(sort==='newest')a.sort((x,y)=>+new Date(y.date)-+new Date(x.date));if(sort==='highest')a.sort((x,y)=>y.rating-x.rating);if(sort==='helpful')a.sort((x,y)=>y.helpful-x.helpful);return a},[product.id,filter,sort,submissions]);const breakdown=ratingBreakdown(product.reviews);return <section id="reviews" className="review-system container"><header><div><span className="eyebrow">BUYER FEEDBACK</span><h2>Product ratings and reviews</h2><p>Review architecture is production-ready. Displayed historical entries and aggregate totals are clearly identified demonstration data.</p></div><button className="btn outline" onClick={()=>setForm(!form)}><PenLine/> Write a review</button></header><div className="review-overview"><div className="review-total"><b>{product.rating}</b><span>★★★★★</span><strong>{product.reviews.toLocaleString()} sample ratings</strong><small>Aggregate preview metric—not verified customer activity</small></div><div className="review-breakdown">{breakdown.map(r=><div key={r.stars}><button onClick={()=>setFilter('all')}>{r.stars} star</button><i><em style={{width:`${r.percent}%`}}/></i><span>{r.count.toLocaleString()}</span></div>)}</div><div className="review-topics"><b>Buyer feedback topics</b>{['Product information','Case packaging','Ordering clarity','Documentation','Account support'].map((x,i)=><span key={x}>{x}<small>{92-i*3}% positive*</small></span>)}<em>*Demonstration topic analysis</em></div></div>{form&&<ReviewForm product={product} onSubmit={r=>{setSubmissions(s=>[r,...s]);setForm(false)}}/>}<div className="review-controls"><div><button className={filter==='all'?'active':''} onClick={()=>setFilter('all')}>All reviews</button><button className={filter==='verified'?'active':''} onClick={()=>setFilter('verified')}><ShieldCheck/> Verified purchaser</button><button className={filter==='photos'?'active':''} onClick={()=>setFilter('photos')}><ImageIcon/> With photos</button></div><label>Sort by<select value={sort} onChange={e=>setSort(e.target.value)}><option value="relevant">Most relevant</option><option value="newest">Newest</option><option value="highest">Highest rated</option><option value="helpful">Most helpful</option></select></label></div>{reviews.length?<div className="professional-review-list">{reviews.map(r=><article key={r.id}><aside><span>{r.buyerType[0]}</span><b>{r.buyerType}</b><small>{r.location}</small>{r.verified&&<em><Check/> Verified purchaser</em>}{r.sample&&<i>DEMO REVIEW</i>}</aside><main><div className="review-meta"><span>{'★'.repeat(r.rating)}{'☆'.repeat(5-r.rating)}</span><time>{new Date(r.date).toLocaleDateString('en-US',{year:'numeric',month:'long',day:'numeric'})}</time></div><h3>{r.title}</h3><p>{r.body}</p>{r.hasPhotos&&<div className="review-photo-placeholder"><ImageIcon/> Photo-review interface preview</div>}<div className="review-vote"><span>Was this helpful?</span><button className={votes[r.id]==='up'?'active':''} onClick={()=>setVotes(v=>({...v,[r.id]:'up'}))}><ThumbsUp/> {r.helpful+(votes[r.id]==='up'?1:0)}</button><button className={votes[r.id]==='down'?'active':''} onClick={()=>setVotes(v=>({...v,[r.id]:'down'}))}><ThumbsDown/> {r.unhelpful+(votes[r.id]==='down'?1:0)}</button><button disabled={reported.includes(r.id)} onClick={()=>setReported(x=>[...x,r.id])}>{reported.includes(r.id)?'Reported':'Report'}</button></div></main></article>)}</div>:<div className="reviews-empty"><span>☆</span><h3>No reviews match this filter</h3><p>Try another filter or submit the first review for this view.</p><button className="btn dark" onClick={()=>setForm(true)}>Write a review</button></div>}<footer><b>Review integrity</b><p>Only feedback connected to an eligible transaction should receive a verified-purchaser badge in production. Demonstration reviews are labeled and must be replaced or removed before public launch.</p></footer></section>}
function ReviewForm({product,onSubmit}:{product:Product;onSubmit:(r:Review)=>void}){const[rating,setRating]=useState(5);const[title,setTitle]=useState('');const[body,setBody]=useState('');return <form className="review-form" onSubmit={e=>{e.preventDefault();const review:Review={id:`local-${Date.now()}`,productId:product.id,rating,title,body,date:new Date().toISOString(),verified:false,helpful:0,unhelpful:0,buyerType:'Local preview submission',location:'Frontend session',sample:true,hasPhotos:false};appendAdminRow('reviews',[product.name,`${rating} stars`,'Frontend buyer','Pending','Review']);onSubmit(review)}}><div><span className="eyebrow">REVIEW PREVIEW</span><h3>Share product feedback</h3><p>This frontend submission stays in the current session and is visibly treated as demonstration content.</p></div><label>Overall rating<div className="review-star-input">{[1,2,3,4,5].map(n=><button type="button" className={n<=rating?'active':''} onClick={()=>setRating(n)} key={n}>★</button>)}</div></label><label>Review title<input required value={title} onChange={e=>setTitle(e.target.value)} maxLength={80}/></label><label>Your review<textarea required rows={5} value={body} onChange={e=>setBody(e.target.value)} maxLength={800}/></label><label className="review-upload"><ImageIcon/> Add product photos<input type="file" multiple accept="image/*"/></label><div><button className="btn dark">Submit preview review</button></div></form>}
